(function(){const toggle=document.getElementById('uChatToggle'),panel=document.getElementById('uChatPanel'),close=document.getElementById('uChatClose'),body=document.getElementById('uChatBody');if(!toggle||!panel)return;toggle.addEventListener('click',()=>panel.hidden=!panel.hidden);close.addEventListener('click',()=>panel.hidden=true);const answers={booking:'Buka Cari Lapangan, pilih venue, tentukan tanggal, jam mulai, durasi, dan metode pembayaran. Jadwal yang sudah terpakai akan ditolak sistem.',payment:'Buka Riwayat Booking untuk melihat detail transaksi dan status pembayaran. Pembayaran diproses otomatis melalui Midtrans.',points:'Poin dapat ditukar di menu Tukar Poin. Pastikan saldo poin mencukupi; poin yang digunakan akan dipotong dari saldo.',match:'Open Match dipakai untuk mencari pemain lain. Pembuatannya memerlukan booking aktif pada tanggal mendatang.'};body.querySelectorAll('[data-faq]').forEach(btn=>btn.addEventListener('click',()=>{const bubble=document.createElement('div');bubble.className='u-chat-bubble';bubble.textContent=answers[btn.dataset.faq]||'Silakan hubungi pengelola untuk bantuan lebih lanjut.';body.appendChild(bubble);body.scrollTop=body.scrollHeight;}));})();
</script></body></html>
